def get_proof(self):
    """
        Get a proof produced when deciding the formula.
    """

    if self.cadical and self.prfile:
        pysolvers.flushpr(self.prfp)
        self.prfile.seek(0)

        # stripping may cause issues here!
        return Solver._proof_bin2text(bytearray(self.prfile.read()).strip())

